changeSet.sql:
ALTER TABLE zc_outcome_observation
  ADD CONSTRAINT fk_zc_outcome_observation_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
-- measure_version must match the definition.
ALTER TABLE zc_outcome_observation
  ADD CONSTRAINT fk_zc_outcome_observation_definition
    FOREIGN KEY (tenant_id, outcome_definition_id, measure_version)
    REFERENCES zc_outcome_definition (tenant_id, id, measure_version);
ALTER TABLE zc_outcome_observation
  ADD CONSTRAINT fk_zc_outcome_observation_enrolment FOREIGN KEY (tenant_id, enrolment_id)
    REFERENCES zc_enrolment (tenant_id, id);

ALTER TABLE zc_report_snapshot
  ADD CONSTRAINT fk_zc_report_snapshot_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_report_snapshot
  ADD CONSTRAINT fk_zc_report_snapshot_programme_version FOREIGN KEY (tenant_id, programme_version_id)
    REFERENCES zc_programme_version (tenant_id, id);

-- Tenant isolation. The app must connect as zc_app: superusers bypass RLS.
ALTER TABLE zc_outcome_observation ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_outcome_observation FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_outcome_observation_tenant ON zc_outcome_observation
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_report_snapshot ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_report_snapshot FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_report_snapshot_tenant ON zc_report_snapshot
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());

rollback.sql:
DROP POLICY rls_zc_outcome_observation_tenant ON zc_outcome_observation;
ALTER TABLE zc_outcome_observation NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_outcome_observation DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_report_snapshot_tenant ON zc_report_snapshot;
ALTER TABLE zc_report_snapshot NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_report_snapshot DISABLE ROW LEVEL SECURITY;

changeSet.sql:
GRANT SELECT, INSERT, UPDATE ON zc_outcome_observation TO zc_app;
GRANT USAGE ON SEQUENCE zc_outcome_observation_id_seq TO zc_app;
GRANT SELECT, INSERT ON zc_report_snapshot TO zc_app;
REVOKE UPDATE, DELETE, TRUNCATE ON zc_report_snapshot FROM zc_app;
GRANT USAGE ON SEQUENCE zc_report_snapshot_id_seq TO zc_app;

rollback.sql:
REVOKE ALL ON zc_outcome_observation FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_outcome_observation_id_seq FROM zc_app;
REVOKE ALL ON zc_report_snapshot FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_report_snapshot_id_seq FROM zc_app;
